const i={web3_267:{lianjieqianbao:"Conectar Cartera",wodeqianbaodizhi:"Mi Dirección de Cartera",licai:"Minería",jinrulicai:"Entrar en Minería",yishouyi:"Ingresos Obtenidos",shouyilv:"Tasa de Rendimiento",zhiyajine:"Monto de Minería",canyu:"Participar",shouyishijian:"Tiempo de Ganancias {amount}/{time}",yifafangshouyi:"Ganancias Distribuidas",licaishuju:"Datos de Minería",zongchanliang:"Producción Total",youxiaojiedian:"Nodos Válidos",canyuzhe:"Participantes",yonghushouru:"Ingresos del Usuario",liudongxinglicaishouyi:"Ganancias de Minería de Liquidez",shouyi:"Ganancias",licaishuoming:"Explicación de Minería",weishenmeyaolicai:"¿Por qué minar?",weishenmeyaolicai_desc:"La minería es el proceso de aumentar los activos asignando fondos de manera razonable y utilizando diversas herramientas financieras. La minería efectiva puede contrarrestar la inflación, aumentar los ingresos pasivos, lograr la libertad financiera y alcanzar la jubilación anticipada.",licaifengxian:"¿Qué riesgos tiene la minería?",licaifengxian_desc:"Los riesgos de la minería incluyen riesgo de mercado, riesgo de inflación, riesgo de liquidez, riesgo crediticio y riesgo operativo. Los inversores deben elegir productos adecuados según su tolerancia al riesgo y diversificar los activos para reducir riesgos.",xinshoruhekaishilicai:"¿Cómo pueden empezar los principiantes en la minería?",xinshoruhekaishilicai_desc:"Los principiantes deben primero crear un fondo de emergencia, entender su situación financiera, establecer objetivos, aprender conocimientos básicos de inversión, comenzar con productos de bajo riesgo, expandir gradualmente su portafolio y seguir aprendiendo y ajustando estrategias.",qukuailianlicai_youshi:"¿Cuáles son las ventajas de la minería en blockchain?",qukuailianlicai_youshi_desc:"La minería en blockchain tiene ventajas como descentralización, alta transparencia, bajos costos de transacción, accesibilidad global y ejecución automática de contratos inteligentes, ofreciendo soluciones innovadoras para el mercado minero tradicional.",liudongxingzhiyashishenme:"¿Qué es la minería de liquidez?",liudongxingzhiyashishenme_desc:"La minería de liquidez es el proceso de bloquear criptoactivos en un protocolo DeFi para proporcionar liquidez y obtener recompensas. Los mineros suelen recibir una parte de las comisiones de transacción y recompensas en tokens de gobernanza, siendo un método popular de ingresos pasivos.",ruhepinggulicaichanpindefengxian:"¿Cómo evaluar los riesgos de los productos de minería?",ruhepinggulicaichanpindefengxian_desc:"Para evaluar los riesgos de los productos de minería, se deben considerar la volatilidad de los ingresos, el rendimiento histórico, la liquidez, la reputación del emisor, la duración de la inversión y el entorno del mercado, junto con la tolerancia personal al riesgo.",shouyibiao:"Tabla de Ganancias",meirishouyi:"Ganancias Diarias"}};export{i as default};
